def shade(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr(); shd = OxmlElement('w:shd'); shd.set(qn('w:fill'), fill); tcPr.append(shd)

def border(cell, color='D9E2F3'):
    tcPr = cell._tc.get_or_add_tcPr(); b = OxmlElement('w:tcBorders')
    for side in ('top','left','bottom','right'):
        x = OxmlElement('w:' + side); x.set(qn('w:val'),'single'); x.set(qn('w:sz'),'4'); x.set(qn('w:color'),color); b.append(x)
    tcPr.append(b)

def set_cell_text(cell, value, bold=False):
    cell.text = ''
    p=cell.paragraphs[0]; r=p.add_run(str(value)); r.bold=bold; r.font.size=Pt(8.5); p.paragraph_format.space_after=Pt(0)
    cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; border(cell)

def field(paragraph, code):
    run=paragraph.add_run(); begin=OxmlElement('w:fldChar'); begin.set(qn('w:fldCharType'),'begin')
    instr=OxmlElement('w:instrText'); instr.set(qn('xml:space'),'preserve'); instr.text=code
    sep=OxmlElement('w:fldChar'); sep.set(qn('w:fldCharType'),'separate'); end=OxmlElement('w:fldChar'); end.set(qn('w:fldCharType'),'end')
    run._r.extend([begin,instr,sep,end])

def page_number(paragraph): field(paragraph, 'PAGE')

d=Document()
