styles['Normal'].font.name='Aptos'; styles['Normal'].font.size=Pt(10.5); styles['Normal']._element.rPr.rFonts.set(qn('w:eastAsia'),'Aptos')
styles['Normal'].paragraph_format.line_spacing=1.25; styles['Normal'].paragraph_format.space_after=Pt(7)
for style,size,color in [('Title',23,'0B4F6C'),('Heading 1',16,'0B4F6C'),('Heading 2',13,'176B87'),('Heading 3',11,'176B87')]:
    s=styles[style]; s.font.name='Aptos Display'; s.font.size=Pt(size); s.font.color.rgb=RGBColor.from_string(color); s.font.bold=True
    s.paragraph_format.space_before=Pt(14); s.paragraph_format.space_after=Pt(7)
if 'Caption' in styles: styles['Caption'].font.name='Aptos'; styles['Caption'].font.size=Pt(9); styles['Caption'].font.italic=True
