def p(text='', style=None, align=None):
    x=d.add_paragraph(style=style); x.add_run(text)
    if align is not None: x.alignment=align
    return x
def heading(text, level=1): return d.add_heading(text, level=level)
def bullet(text): return p(text,'List Bullet')
def placeholder(label, caption, explanation='Insert the verified project artefact here. Do not use a mock or illustrative image.'):
    x=p(label, align=WD_ALIGN_PARAGRAPH.CENTER); x.runs[0].bold=True; x.runs[0].font.color.rgb=RGBColor.from_string('7A4E00')
    y=p(caption,'Caption',WD_ALIGN_PARAGRAPH.CENTER); y.runs[0].bold=True
    p(explanation,'Caption',WD_ALIGN_PARAGRAPH.CENTER)
def table(headers, rows, widths=None):
    t=d.add_table(rows=1, cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for i,h in enumerate(headers): set_cell_text(t.rows[0].cells[i],h,True); shade(t.rows[0].cells[i],'0B4F6C');
    for c in t.rows[0].cells:
        for r in c.paragraphs[0].runs: r.font.color.rgb=RGBColor(255,255,255)
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row): set_cell_text(cells[i],v)
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths): row.cells[i].width=Inches(w)
    d.add_paragraph('')
    return t
def chapter(title):
    d.add_page_break(); heading(title,1)
def auto_list(title, code, prompt):
    heading(title,1); q=p(prompt); q.runs[0].italic=True; field(p(),code)

